import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.BqDA2HS7.js";const r="/RefractRouter/strategy-composite.svg",i="/RefractRouter/screenshots/dsh-20261014/strategy-composite-settings.png",d="/RefractRouter/screenshots/dsh-20261014/strategy-composite-judge.png",k=JSON.parse('{"title":"Composite · 组合","description":"","frontmatter":{},"headers":[],"relativePath":"strategies/composite.md","filePath":"strategies/composite.md"}'),c={name:"strategies/composite.md"};function n(g,e,p,l,h,m){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="composite-·-组合" tabindex="-1">Composite · 组合 <a class="header-anchor" href="#composite-·-组合" aria-label="Permalink to &quot;Composite · 组合&quot;">​</a></h1><p>Composite 将 Task 的任务级初选，与 Stage 的后续轨迹判断组合。 它使用自己的模型池与 Judge 设置，不创建 DAG。</p><figure class="doc-diagram"><img src="'+r+'" alt="Composite 先 Task 初选常用模型，再按 Stage 规则临时切换到接管模型"><figcaption>常用模型是任务默认档位；接管模型既是临时升级目标，也是 Task 不确定时的备援。</figcaption></figure><h2 id="task-与-stage-的交接" tabindex="-1">Task 与 Stage 的交接 <a class="header-anchor" href="#task-与-stage-的交接" aria-label="Permalink to &quot;Task 与 Stage 的交接&quot;">​</a></h2><ol><li>Task 在任务开始从池中选定常用模型；单候选跳过 Judge。</li><li>第一次执行直接使用常用模型，不紧接着追加 Stage Judge。</li><li>后续消费新增工具证据，必要时临时切换到指定接管模型。</li><li>保持期结束且没有新困难时恢复 Task 选出的常用模型。</li></ol><p>指定接管模型也作为 Task 正常不确定时的备援。如果初选已是接管模型，继续使用它， 跳过没有实际切换意义的判断；轨迹明确说明两者相同。</p><h2 id="两种逐轮模式" tabindex="-1">两种逐轮模式 <a class="header-anchor" href="#两种逐轮模式" aria-label="Permalink to &quot;两种逐轮模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>行为</th></tr></thead><tbody><tr><td>规则</td><td>默认窗口 3、阈值 0.5、保持 2；新增可信重复失败触发接管</td></tr><tr><td>规则＋Jev／Laya</td><td>实验协作；配置判别间隔、批次上限及降回确认</td></tr></tbody></table><p>协作模式默认隔两次执行判别，每任务最多四批，降回需要两次明确支持。 判别额度耗尽时记录冻结或保守接管原因，不继续无限追加 Judge。 本地未就绪、推论超时或进程故障按各自停止规则处理。</p><h2 id="必要设置" tabindex="-1">必要设置 <a class="header-anchor" href="#必要设置" aria-label="Permalink to &quot;必要设置&quot;">​</a></h2><p>独立模型池、Task Judge、指定接管模型、Stage 模式与参数。 接管模型必须满足能力、数据域、历史和预算要求；其角色名不证明更强。</p><h2 id="系统设置示范" tabindex="-1">系统设置示范 <a class="header-anchor" href="#系统设置示范" aria-label="Permalink to &quot;系统设置示范&quot;">​</a></h2><p>打开 <strong>规划路由 → 正在编辑的策略：Composite</strong>，分别配置初选池、Task Judge 与后续轨迹规则。</p><figure class="doc-screenshot"><a href="/screenshots/dsh-20261014/strategy-composite-settings.png" target="_blank" rel="noopener"><img src="'+i+'" alt="实际 Composite 设置上半区：Task 初选执行模型池"></a><figcaption>2026-10-14 实际界面：常用模型从这个独立模型池选出，第一次执行直接用它。</figcaption></figure><figure class="doc-screenshot"><a href="/screenshots/dsh-20261014/strategy-composite-judge.png" target="_blank" rel="noopener"><img src="'+d+'" alt="实际 Composite 设置下半区：V4.1 接管模型、GLM Task Judge、后续规则判断"></a><figcaption>同一卡片向下滚动：指定接管模型同时作为初选不确定时的备援；Task Judge 与逐轮规则分别设置。</figcaption></figure><p>截图使用 GLM Flash 作一次 Task Judge，接管角色为 V4.1 Flash，后续选择纯规则模式。 因此有两轮执行也不等于调用两次 Task Judge；纯规则判断不会产生第二条 Judge 账单。 如果 Task 一开始选中的就是接管模型，核心记录 <code>composite-base-is-takeover</code>， 跳过没有实际切换意义的判断。</p><p>适用场景是多任务编码队列：Task 为每项任务选常用模型，Stage 再处理该任务中新出现的 持续困难。它需要同时验收初选与接管，费用应包含 Task 判别、所有执行与失败尝试。</p><h2 id="费用与轨迹" tabindex="-1">费用与轨迹 <a class="header-anchor" href="#费用与轨迹" aria-label="Permalink to &quot;费用与轨迹&quot;">​</a></h2><p>Task 一次判别与逐轮执行分别计账；纯规则 Stage 不增加 Judge。 只预留本轮选中执行模型的费用，接管余额不足明确停止，不静默降档。 轨迹包含初选、证据、保持、恢复和任何实验 Judge 的原始结果。</p><h3 id="真实案例" tabindex="-1">真实案例 <a class="header-anchor" href="#真实案例" aria-label="Permalink to &quot;真实案例&quot;">​</a></h3><p>composite-01 任务：先由 Task 阶段的 Judge <code>glm-5.3-flash</code> 分类并选出常用模型 （<code>task-llm-judge</code> → <code>composite-task-selected</code>），执行轮次交回 Stage 规则判断； 任务要求只调用一次终端工具执行 <code>printf %s COMPOSITE_01_OK</code>，再回复该标记。 工具回执 <code>ambiguous</code> 时使用常用模型（<code>composite-ambiguous-base</code>），由 <code>deepseek-v4-flash</code> 接续执行，<strong>本例未触发接管</strong>。 共 3 次受管调用（1 判别 + 2 执行），费用 1.408 AFP， 首字 3.21 秒，总延迟 7.66 秒。 接管、保持和返回分支使用确定性夹具验证，证据范围见<a href="./../planning.html#六策略真实运行案例">历史验收报告</a>。</p>',21)])])}const f=a(c,[["render",n]]);export{k as __pageData,f as default};
